(() => {
  if (window.__spmtEmojiFontsInstalled || typeof FontFace !== 'function') return;
  window.__spmtEmojiFontsInstalled = true;
  const bytes = Uint8Array.from(atob(''), character => character.charCodeAt(0));
  const unicodeRange = 'U+00A9,U+00AE,U+203C,U+2049,U+2122,U+2139,U+2190-23FF,U+25A0-27FF,U+2934-2935,U+2B00-2BFF,U+3030,U+303D,U+3297,U+3299,U+1F000-1FAFF';
  const families = ['Segoe UI', 'Arial', 'Inter', 'Roboto', 'Noto Sans', 'Helvetica', 'Helvetica Neue', 'Verdana', 'Tahoma', 'Trebuchet MS', 'Geist', 'Geist Sans'];
  window.__spmtEmojiFontsReady = Promise.all(families.map(async family => {
    const face = new FontFace(family, bytes, { unicodeRange, weight: '100 900', style: 'normal' });
    await face.load();
    document.fonts.add(face);
  })).catch(error => console.warn('[SPMT] Overlay emoji font failed to load', error?.message || String(error)));
})();
